root_hcl.content:
locals {
  account_vars = read_terragrunt_config(find_in_parent_folders("account.hcl"))
  region_vars  = read_terragrunt_config(find_in_parent_folders("region.hcl"))

  account_name = local.account_vars.locals.account_name
  account_id   = local.account_vars.locals.aws_account_id
  aws_region   = local.region_vars.locals.aws_region
}

generate "provider" {
  path      = "provider.tf"
  if_exists = "overwrite_terragrunt"
  contents  = <<EOF
provider "aws" {
  region = "${local.aws_region}"

  allowed_account_ids = ["${local.account_id}"]
}
EOF
}

remote_state {
  backend = "s3"
  config = {
    encrypt        = true
    bucket         = "terraform-state-${local.account_name}"
    key            = "${path_relative_to_include()}/terraform.tfstate"
    region         = local.aws_region
    dynamodb_table = "terraform-locks"
  }
  generate = {
    path      = "backend.tf"
    if_exists = "overwrite_terragrunt"
  }
}

stack_hcl.content:
unit "mysql_db" {
  source = "git::git@github.com:gruntwork-io/terragrunt-infrastructure-modules-example.git//mysql?ref=v0.8.0"

  values = {
    name              = "mysql_db"
    instance_class    = "db.t2.micro"
    allocated_storage = 20
    engine_version    = "5.7.21"

    master_username = "admin"
    master_password = get_env("MYSQL_MASTER_PASSWORD")
  }
}

unit "asg" {
  source = "git::git@github.com:gruntwork-io/terragrunt-infrastructure-modules-example.git//asg-rolling-deploy?ref=v0.8.0"

  depends_on = ["mysql_db"]

  values = {
    instance_type     = "t2.micro"
    min_size          = 1
    max_size          = 3
    server_port       = 8080

    mysql_config = dependency.mysql_db.outputs
  }
}

root_hcl.content:
locals {
  subscription_vars = read_terragrunt_config(find_in_parent_folders("subscription.hcl"))
  site_vars        = read_terragrunt_config(find_in_parent_folders("site.hcl"))
  stack_vars       = read_terragrunt_config(find_in_parent_folders("stack.hcl"))

  subscription_id = local.subscription_vars.locals.subscription_id
  tenant_id       = local.subscription_vars.locals.tenant_id
  location        = local.site_vars.locals.location
}

generate "provider" {
  path      = "provider.tf"
  if_exists = "overwrite_terragrunt"
  contents  = <<EOF
provider "azurerm" {
  features {
    key_vault {
      purge_soft_deleted_secrets_on_destroy = true
      recover_soft_deleted_secrets          = true
    }
  }

  subscription_id    = "${local.subscription_id}"
  tenant_id          = "${local.tenant_id}"
  storage_use_azuread = true
}
EOF
}

remote_state {
  backend = "azurerm"
  config = {
    subscription_id      = local.subscription_id
    resource_group_name  = local.subscription_vars.locals.deployment_storage_resource_group_name
    storage_account_name = local.subscription_vars.locals.deployment_storage_account_name
    container_name       = local.subscription_vars.locals.tf_container_name
    key                  = "${path_relative_to_include("site")}/terraform.tfstate"
  }
}

terraform {
  extra_arguments "retry_lock" {
    commands = get_terraform_commands_that_need_locking()
    arguments = [
      "-lock-timeout=20m"
    ]
  }

  extra_arguments "parallelism" {
    commands = [
      "apply",
      "plan",
      "destroy"
    ]
    arguments = [
      "-parallelism=10"
    ]
  }
}

stack_hcl.content:
locals {
  subscription_vars = read_terragrunt_config(find_in_parent_folders("subscription.hcl"))
  site_vars        = read_terragrunt_config(find_in_parent_folders("site.hcl"))

  stack = "dev1"

  default_tags = {
    Environment = local.subscription_vars.locals.environment
    ManagedBy   = "Terraform"
    Owner       = "DevOps Team"
  }
}

envcommon_unit.content:
locals {
  stack_vars        = read_terragrunt_config(find_in_parent_folders("stack.hcl"))
  site_vars         = read_terragrunt_config(find_in_parent_folders("site.hcl"))
  subscription_vars = read_terragrunt_config(find_in_parent_folders("subscription.hcl"))

  base_source_url = "git::https://github.com/example/terraform-modules.git//modules/unit1"
}

inputs = {
  resource_group_name = "rg-${get_env("USER", "default")}-${local.stack_vars.locals.stack}"
  location            = local.site_vars.locals.location

  default_tags = merge(
    local.stack_vars.locals.default_tags,
    {
      Component = "unit1"
    }
  )
}

unit_terragrunt.content:
include "root" {
  path           = find_in_parent_folders("root.hcl")
  merge_strategy = "deep"
}

include "envcommon" {
  path           = "${get_repo_root()}/_envcommon/unit1.hcl"
  expose         = true
  merge_strategy = "deep"
}

terraform {
  source = "${include.envcommon.locals.base_source_url}?ref=main"
}

inputs = {
  project_name = "Custom Project"
  enable_feature_x = true
}
